using NUnit.Framework;

namespace Enterprise.Customs.GB.Chief.CusRes.Testing
{
	public class EdifactParserTests : TestCase
	{
		public void TestGetItemNumber()
		{
			string twoLineItem = "UNH+1+CUSDEC:D:04A:UN:109700+<<SYSCAR>>'BGM+IFD::109++9'CST++IMD+2'LOC+14+GBFXT::109'LOC+35+WW'LOC+11+GBFXT'GEI+5+ACC:PI:109'RFF+ABO:8-B00001000'RFF+UCN'TDT+13++1'NAD+CZ+++CHERRY BODY FASHION+UNIT B 4/F WINNER BUILDING+KOWLOON, HONG KONG++NA+HK'NAD+CN+GB543938615000++THE BODY SHOP+THE REGIONAL DISTRIBUTION CENTRE+LITTLEHAMPTON++BN17 6LS+GB'NAD+DT+GB945390992000++DANIEL MAIN ORG+314 MIDSUMMER BLVD+MLITON KEYNES++MK9 2UB+GB'UNS+D'DMS+B00001205'MOA+39:10000.00:GBP'CST++4000000+6403911898+A999++100'FTX+ACB++LIC99'LOC+27+CN'MEA+AAR++KGM:50'MEA+AAS++ZZZ:1'PAC+1++PK'PCI++ASDADS'MOA+38:10000'RFF+ZZZ'IMD+++:::COVERING THE ANKLE BUT NO PART OF THE CALF, WITH INSOLES OF A LENGTH  OF 24 CM OR MORE  OTHER THAN FOOTWEAR WHICH CANNOT BE IDENTIFIED AS MEN S OR WOMEN S FOOTWEAR FOR WOMEN; EXCLUDING THOSE SHOES WHICH HAVE A CIF PRICE PER PAIR OF NOT LESS THAN EURO 9 FO: USE IN SPORTING ACTIVIT'DOC+998:::380+ASDADASDA:::::Z'DOC+916:::N934+:JE'GEI+2+1:VM:109'GEI+2+B:VA:109'PCD+9:0'TAX+1+B00+D++S::::::109'MOA+161'TAX+1+A00+D++F::::::109'MOA+161'TAX+1+A30+D++::::::109'MOA+161'CST++4000000+6403911898+A999++100'FTX+ACB++LIC99'LOC+27+CN'MEA+AAR++KGM:50'MEA+AAS++ZZZ:1'PAC+1++PK'PCI++ASDADS'MOA+38:10000'RFF+ZZZ'IMD+++:::COVERING THE ANKLE BUT NO PART OF THE CALF, WITH INSOLES OF A LENGTH  OF 24 CM OR MORE  OTHER THAN FOOTWEAR WHICH CANNOT BE IDENTIFIED AS MEN S OR WOMEN S FOOTWEAR FOR WOMEN; EXCLUDING THOSE SHOES WHICH HAVE A CIF PRICE PER PAIR OF NOT LESS THAN EURO 9 FO: USE IN SPORTING ACTIVIT'DOC+998:::380+ASDADASDA:::::Z'DOC+916:::N934+:JE'GEI+2+1:VM:109'GEI+2+B:VA:109'PCD+9:0'TAX+1+B00+D++S::::::109'MOA+161'TAX+1+A00+D++F::::::109'MOA+161'TAX+1+A30+D++::::::109'MOA+161'UNS+S'CNT+11:1'UNT+40+1'";
			AssertEquals(0, CusResEdifactParser.GetItemNumber(twoLineItem, 3, "'"));  // segment 3 is in the header, not a line item
			AssertEquals(0, CusResEdifactParser.GetItemNumber(twoLineItem, 7, "'"));  // segment 7 is in the header, not a line item
			AssertEquals(1, CusResEdifactParser.GetItemNumber(twoLineItem, 19, "'"));  // segment 19 is in the first line item
			AssertEquals(2, CusResEdifactParser.GetItemNumber(twoLineItem, 53, "'"));  // segment 53 is in the second line item
		}

