AX+1+A00+F++F::::::109'CST++4000000+9029100090+++100'LOC+27+CN'MEA+AAR++KGM:150'PAC+10++CT'PCI++AS ADDR'MOA+38:3150'RFF+AAQ:BEAU5297774'RFF+ZZZ'IMD+++:::PEDOMETER'DOC+998:::380+19B239A:::::Z'DOC+916:::N934+:JE'GEI+2+1:VM:109'GEI+2+A:VA:109'PCD+9:0'TAX+1+B00+F++S::::::109'TAX+1+A00+F++F::::::109'UNS+S'CNT+11:167'UNT+120+25639'";
			AssertEquals(0, CusResEdifactParser.GetItemNumber(sixLineCusdec, 3, "'"));    // segment   3 is in the header, not a line item
			AssertEquals(0, CusResEdifactParser.GetItemNumber(sixLineCusdec, 7, "'"));    // segment   7 is in the header, not a line item
			AssertEquals(1, CusResEdifactParser.GetItemNumber(sixLineCusdec, 29, "'"));   // segment  29 is in line item 1
			AssertEquals(2, CusResEdifactParser.GetItemNumber(sixLineCusdec, 45, "'"));   // segment  45 is in line item 2
			AssertEquals(3, CusResEdifactParser.GetItemNumber(sixLineCusdec, 61, "'"));   // segment  61 is in line item 3
			AssertEquals(4, CusResEdifactParser.GetItemNumber(sixLineCusdec, 75, "'"));   // segment  75 is in line item 4
			AssertEquals(5, CusResEdifactParser.GetItemNumber(sixLineCusdec, 100, "'"));  // segment 100 is in line item 5
			AssertEquals(6, CusResEdifactParser.GetItemNumber(sixLineCusdec, 115, "'"));  // segment 115 is in line item 6
		}
	}
}
